(() => {
                        const q = leadSearch.toLowerCase();
                        const filtered = employees
                          .filter(
                            (emp) =>
                              `${emp.first_name} ${emp.last_name}`
                                .toLowerCase()
                                .includes(q) ||
                              (emp.email ?? "").toLowerCase().includes(q)
                          )
                          .slice(0, 50);
                        if (filtered.length === 0) {
                          return (
                            <div className="px-3 py-4 text-center text-[12px] text-gray-600">
                              No employees match your search.
                            </div>
                          );
                        }
                        return (
                          <ul className="divide-y divide-gray-100">
                            {filtered.map((emp) => {
                              const selected = form.lead_ids.includes(emp.id);
                              const name =
                                `${emp.first_name ?? ""} ${emp.last_name ?? ""}`.trim() ||
                                emp.username ||
                                emp.email;
                              return (
                                <li key={emp.id}>
                                  <button
                                    type="button"
                                    onClick={() =>
                                      set(
                                        "lead_ids",
                                        selected
                                          ? form.lead_ids.filter(
                                              (x) => x !== emp.id
                                            )
                                          : [...form.lead_ids, emp.id]
                                      )
                                    }
                                    className={cn(
                                      "flex w-full items-center gap-2.5 px-3 py-2 text-left text-[13px] transition-colors",
                                      selected
                                        ? "bg-gray-100 font-medium text-gray-900"
                                        : "text-gray-800 hover:bg-gray-50"
                                    )}
                                  >
                                    <span
                                      className={cn(
                                        "grid h-4 w-4 shrink-0 place-items-center rounded border",
                                        selected
                                          ? "border-gray-900 bg-gray-900 text-white"
                                          : "border-gray-300 bg-white"
                                      )}
                                    >
                                      {selected ? (
                                        <Check className="h-3 w-3" />
                                      ) : null}
                                    </span>
                                    <span className="flex-1 truncate">
                                      {name}
                                    </span>
                                    <span className="truncate text-[11px] text-gray-600">
                                      {emp.role?.name || emp.department || ""}
                                    </span>
                                  </button>
                                </li>
                              );
                            })}
                          </ul>
                        );
                      })

(() => {
                        if (form.lead_ids.length === 0) return "—";
                        const names = form.lead_ids.map((id) => {
                          const emp = employees.find((e) => e.id === id);
                          if (!emp) return `Employee #${id}`;
                          return (
                            `${emp.first_name ?? ""} ${emp.last_name ?? ""}`.trim() ||
                            emp.username ||
                            emp.email
                          );
                        });
                        return names.join(", ");
                      })
